emit_menubar_tray_py() {
cat <<'COVE_MENUBAR_TRAY_EOF'
#!/usr/bin/env python3
# Cove Menu Bar for Linux — a system tray companion for Cove.
#
# The Linux sibling of Sources/main.m. Same contract, same menu: status is
# read via `cove status --porcelain` (key=value per line, defined in
# commands/status — never change those keys without updating both apps),
# actions shell out to `cove`, and the icon tells the story at a glance:
# full colour when Caddy, MariaDB and Mailpit are all up, light grey when
# some are, dark grey when everything is stopped.
#
# It is a StatusNotifierItem (the freedesktop tray protocol) published through
# AyatanaAppIndicator3, so it shows up on any desktop that hosts a tray:
# COSMIC, KDE, XFCE, MATE, Cinnamon, and GNOME with the AppIndicator extension
# (Ubuntu ships it enabled; vanilla GNOME and Debian do not). The menu itself
# is rendered by the desktop's panel over DBus, which is why there is no
# Option-key trick here: the panel never tells us which modifiers were held.
# WordPress sites therefore get a second, indented "Log in as admin" row right
# under their open row. Not a nested submenu: COSMIC's panel renders submenus
# inline and cannot drill into a second level at all.
#
# Written out and launched by `cove menubar enable`; there is no build step.
# Runtime needs: python3, GTK 3 and AyatanaAppIndicator3 introspection data
# (Debian/Ubuntu: python3-gi gir1.2-gtk-3.0 gir1.2-ayatanaappindicator3-0.1).
# gir1.2-notify-0.7 is optional and only used for desktop notifications.

import os
import re
import shutil
import subprocess
import sys
import threading
import time
import urllib.request
from datetime import datetime

import gi

gi.require_version("Gtk", "3.0")
gi.require_version("AyatanaAppIndicator3", "0.1")
from gi.repository import Gtk, GLib, AyatanaAppIndicator3 as AppIndicator  # noqa: E402

try:
    gi.require_version("Notify", "0.7")
    from gi.repository import Notify  # noqa: E402
    Notify.init("Cove")
    HAVE_NOTIFY = True
except (ValueError, ImportError):
    HAVE_NOTIFY = False

HOME = os.path.expanduser("~")
COVE_DIR = os.path.join(HOME, "Cove")
SITES_DIR = os.path.join(COVE_DIR, "Sites")
LOGS_DIR = os.path.join(COVE_DIR, "Logs")
INSTALL_DIR = os.path.dirname(os.path.abspath(__file__))
ICON_DIR = os.path.join(INSTALL_DIR, "icons")
AUTOSTART_FILE = os.path.join(HOME, ".config", "autostart", "cove-menubar.desktop")
LOG_FILE = os.path.join(LOGS_DIR, "menubar.log")
REFRESH_SECONDS = 20
UPDATE_CHECK_SECONDS = 86400
CORE_SERVICES = ("caddy", "mariadb", "mailpit")
# Started on demand by the Laravel sites that use them: listed, never counted,
# so a stopped one doesn't make Cove look partly down (as in the macOS app).
OPTIONAL_SERVICES = ("postgres", "redis")
SERVICE_NAMES = {"caddy": "Caddy", "mariadb": "MariaDB", "mailpit": "Mailpit",
                 "postgres": "PostgreSQL", "redis": "Redis"}
URL_PATTERN = re.compile(r"https://[A-Za-z0-9.:/_?=&%~#+!@-]+")
SITE_NAME_PATTERN = re.compile(r"^[a-z0-9]([a-z0-9-]*[a-z0-9])?$")

# Icon colours: the brand disc, then the two greys the macOS app uses for
# "some services" and "everything stopped".
ICON_VARIANTS = {
    "cove-logo": "#009b95",
    "cove-logo-partial": "#9a9a9a",
    "cove-logo-stopped": "#4a4a4a",
}


def log(text):
    try:
        os.makedirs(LOGS_DIR, exist_ok=True)
        with open(LOG_FILE, "a", encoding="utf-8") as handle:
            handle.write(f"[{datetime.now():%Y-%m-%d %H:%M:%S}] {text}\n")
    except OSError:
        pass


def cove_path():
    for candidate in ("/usr/local/bin/cove", "/usr/bin/cove", os.path.join(HOME, ".local", "bin", "cove")):
        if os.access(candidate, os.X_OK):
            return candidate
    return shutil.which("cove") or "cove"


def cove_env():
    env = dict(os.environ)
    env["PATH"] = "/usr/local/bin:/usr/bin:/bin:" + env.get("PATH", "")
    return env


def run_cove(args, timeout):
    """Run a cove subcommand headlessly. Returns (status, merged output, error text)."""
    try:
        result = subprocess.run(
            [cove_path(), *args], capture_output=True, text=True, timeout=timeout,
            env=cove_env(), stdin=subprocess.DEVNULL,
        )
        return result.returncode, (result.stdout or "") + (result.stderr or ""), None
    except subprocess.TimeoutExpired:
        return 1, "", f"cove {' '.join(args)} timed out after {int(timeout)}s."
    except OSError as error:
        return 1, "", str(error)


def strip_ansi(text):
    return re.sub(r"\x1b\[[0-9;]*[A-Za-z]", "", text)


def first_line(text):
    """First meaningful line of command output, with gum's box borders stripped."""
    for line in strip_ansi(text or "").splitlines():
        line = line.strip().strip("│").strip()
        if line and not set(line) <= set("─┌┐└┘╭╮╰╯ "):
            return line
    return ""


def https_port():
    try:
        with open(os.path.join(COVE_DIR, "config"), encoding="utf-8") as handle:
            match = re.search(r"^HTTPS_PORT='?(\d+)'?", handle.read(), re.M)
            return match.group(1) if match else "443"
    except OSError:
        return "443"


def cove_url(host):
    port = https_port()
    return f"https://{host}" if port == "443" else f"https://{host}:{port}"


def open_uri(uri):
    log(f"open {uri}")
    subprocess.Popen(["xdg-open", uri], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def display_name(key):
    if key in SERVICE_NAMES:
        return SERVICE_NAMES[key]
    if key.startswith("php-fpm-"):
        return "PHP-FPM " + key[len("php-fpm-"):]
    return key


def version_tuple(text):
    return tuple(int(part) if part.isdigit() else 0 for part in text.split("."))


def write_icon_variants():
    """Derive the grey icon states from the shipped SVG so all three stay one drawing."""
    source = os.path.join(INSTALL_DIR, "cove-logo.svg")
    try:
        with open(source, encoding="utf-8") as handle:
            svg = handle.read()
    except OSError:
        return
    os.makedirs(ICON_DIR, exist_ok=True)
    for name, colour in ICON_VARIANTS.items():
        try:
            with open(os.path.join(ICON_DIR, f"{name}.svg"), "w", encoding="utf-8") as handle:
                handle.write(svg.replace("#009b95", colour))
        except OSError:
            pass


class CoveTray:
    def __init__(self):
        self.states = {}
        self.service_keys = list(CORE_SERVICES)
        self.states_known = False
        self.busy = None
        self.last_error = None
        self.last_action_error = None
        self.last_user_action = 0.0
        self.pending_stops = set()
        self.cove_version = ""
        self.latest_version = ""
        self.sites_dir_mtime = None

        write_icon_variants()
        self.indicator = AppIndicator.Indicator.new(
            "cove", "cove-logo-partial", AppIndicator.IndicatorCategory.APPLICATION_STATUS)
        self.indicator.set_icon_theme_path(ICON_DIR)
        self.indicator.set_title("Cove")
        self.indicator.set_status(AppIndicator.IndicatorStatus.ACTIVE)

        self.menu = Gtk.Menu()
        self.build_menu()
        self.indicator.set_menu(self.menu)
        self.render()

        self.refresh_status()
        self.check_for_updates()
        GLib.timeout_add_seconds(REFRESH_SECONDS, self.on_refresh_tick)
        GLib.timeout_add_seconds(UPDATE_CHECK_SECONDS, self.on_update_tick)

    # --- Menu skeleton -------------------------------------------------

    def add_item(self, label, callback=None, sensitive=True, menu=None):
        item = Gtk.MenuItem(label=label)
        item.set_sensitive(sensitive)
        if callback is not None:
            item.connect("activate", lambda *_: callback())
        (menu or self.menu).append(item)
        return item

    def add_separator(self, menu=None):
        (menu or self.menu).append(Gtk.SeparatorMenuItem())

    def build_menu(self):
        self.summary_item = self.add_item("Checking Cove…", sensitive=False)
        self.add_separator()
        self.service_items = {}
        self.service_anchor = Gtk.SeparatorMenuItem()
        for key in self.service_keys:
            self.service_items[key] = self.add_item(display_name(key) + ": …", sensitive=False)
        self.error_item = self.add_item("", sensitive=False)
        self.error_item.set_no_show_all(True)
        self.menu.append(self.service_anchor)

        self.action_item = self.add_item("Start Cove", self.toggle_cove)
        self.refresh_item = self.add_item("Refresh Status", self.refresh_status)
        self.reload_item = self.add_item("Reload Caddy", self.reload_caddy)
        self.add_separator()

        self.sites_item = Gtk.MenuItem(label="Sites")
        self.sites_menu = Gtk.Menu()
        self.sites_item.set_submenu(self.sites_menu)
        self.menu.append(self.sites_item)
        self.add_separator()

        self.dashboard_item = self.add_item("Open Dashboard", lambda: open_uri(cove_url("cove.localhost")))
        self.adminer_item = self.add_item("Open Adminer", lambda: open_uri(cove_url("db.cove.localhost")))
        self.mailpit_item = self.add_item("Open Mailpit", lambda: open_uri(cove_url("mail.cove.localhost")))
        self.add_item("Open Cove Logs", lambda: open_uri("file://" + LOGS_DIR))
        self.add_item("Open Sites Folder", lambda: open_uri("file://" + SITES_DIR))
        self.add_separator()

        self.launch_item = Gtk.CheckMenuItem(label="Launch at Login")
        self.launch_item.set_active(os.path.exists(AUTOSTART_FILE))
        self.launch_item.connect("toggled", self.on_launch_toggled)
        self.menu.append(self.launch_item)

        self.version_item = self.add_item("", sensitive=False)
        self.version_item.set_no_show_all(True)
        self.add_item("Quit Cove Menu Bar", Gtk.main_quit)
        self.menu.show_all()
        self.rebuild_sites_menu()

    # --- Rendering (in place, never rebuilds the open menu) --------------

    def all_running(self):
        return self.states_known and all(self.states.get(key) for key in CORE_SERVICES)

    def running(self, key):
        return bool(self.states.get(key))

    def summary_text(self):
        if self.busy:
            return self.busy
        if not self.states_known:
            return "Cove status unavailable" if self.last_error else "Checking Cove…"
        counted = [key for key in self.states if key not in OPTIONAL_SERVICES]
        count = sum(1 for key in counted if self.states.get(key))
        if self.all_running():
            return "Cove is running"
        if count == 0:
            return "Cove is stopped"
        return f"Cove: {count} of {len(counted)} services running"

    def render(self):
        self.summary_item.set_label(self.summary_text())

        error = self.last_action_error or self.last_error
        if error:
            self.error_item.set_label("Error: " + first_line(error))
            self.error_item.show()
        else:
            self.error_item.hide()

        for key in self.service_keys:
            item = self.service_items.get(key)
            if item is None:
                continue
            state = self.states.get(key)
            text = "…" if state is None else ("Running" if state else "Stopped")
            mark = "○" if state is None else ("●" if state else "○")
            item.set_label(f"{mark}  {display_name(key)}: {text}")

        all_up = self.all_running()
        self.action_item.set_label("Stop Cove" if all_up else "Start Cove")
        self.action_item.set_sensitive(self.busy is None)
        self.refresh_item.set_sensitive(self.busy is None)
        self.reload_item.set_sensitive(self.busy is None and self.running("caddy"))
        self.dashboard_item.set_sensitive(self.running("caddy"))
        self.adminer_item.set_sensitive(self.running("caddy"))
        self.mailpit_item.set_sensitive(self.running("mailpit"))

        if self.latest_version and self.cove_version and \
                version_tuple(self.latest_version) > version_tuple(self.cove_version):
            self.version_item.set_label(f"Update Cove to v{self.latest_version}…")
            self.version_item.set_sensitive(True)
            if not getattr(self, "_upgrade_wired", False):
                self.version_item.connect("activate", lambda *_: self.run_upgrade_in_terminal())
                self._upgrade_wired = True
            self.version_item.show()
        elif self.cove_version:
            self.version_item.set_label(f"Cove v{self.cove_version}")
            self.version_item.set_sensitive(False)
            self.version_item.show()
        else:
            self.version_item.hide()

        if not self.states_known:
            icon = "cove-logo-partial"
        elif all_up:
            icon = "cove-logo"
        elif any(v for k, v in self.states.items() if k not in OPTIONAL_SERVICES):
            icon = "cove-logo-partial"
        else:
            icon = "cove-logo-stopped"
        self.indicator.set_icon_full(icon, self.summary_text())

    def sync_service_rows(self, keys):
        """Add rows for services that appear after the first poll (php-fpm pools)."""
        if keys == self.service_keys:
            return
        for key in list(self.service_items):
            if key not in keys:
                self.menu.remove(self.service_items.pop(key))
        # New rows go above the error row, so the service block stays together.
        position = self.menu.get_children().index(self.error_item)
        for key in keys:
            if key in self.service_items:
                continue
            item = Gtk.MenuItem(label=display_name(key) + ": …")
            item.set_sensitive(False)
            item.show()
            self.menu.insert(item, position)
            self.service_items[key] = item
            position += 1
        self.service_keys = list(keys)

    # --- Status polling -------------------------------------------------

    def on_refresh_tick(self):
        self.refresh_status()
        return True

    def refresh_status(self):
        if self.busy:
            return
        threading.Thread(target=self._poll_status, daemon=True).start()

    def _poll_status(self):
        status, output, error = run_cove(["status", "--porcelain"], timeout=30)
        GLib.idle_add(self._apply_status, status, output, error)

    def _apply_status(self, status, output, error):
        if status != 0:
            self.last_error = error or first_line(output) or "Unable to read Cove status."
            self.render()
            return False
        states = {}
        version = self.cove_version
        for line in output.splitlines():
            if "=" not in line:
                continue
            key, value = line.strip().split("=", 1)
            if key == "version":
                version = value
            elif value in ("running", "stopped"):
                states[key] = value == "running"
        if not states:
            self.last_error = "Unexpected status output from Cove."
            self.render()
            return False

        keys = [key for key in CORE_SERVICES if key in states] + \
               sorted(key for key in states if key not in CORE_SERVICES)
        old_states = dict(self.states)
        self.states = states
        self.cove_version = version
        self.last_error = None
        self.sync_service_rows(keys)
        self.notify_unexpected_stops(old_states, states)
        self.states_known = True
        self.render()
        self.rebuild_sites_menu()
        return False

    # Mirrors the macOS app: a service that is newly stopped is held for one
    # more poll before it alarms, everything-stopped-at-once is treated as a
    # deliberate `cove disable`, and nothing fires within 20s of our own action.
    # "Everything" is Cove's own services: `cove disable` leaves PostgreSQL and
    # Redis running, and one still up mustn't make the disable look like a crash.
    def notify_unexpected_stops(self, old_states, new_states):
        if not self.states_known or time.monotonic() - self.last_user_action < 20.0 \
                or not any(v for k, v in new_states.items() if k not in OPTIONAL_SERVICES):
            self.pending_stops.clear()
            return
        still_pending = set()
        for key, running in new_states.items():
            if running:
                continue
            if old_states.get(key):
                still_pending.add(key)
            elif key in self.pending_stops:
                self.notify(f"{display_name(key)} stopped unexpectedly.")
        self.pending_stops = still_pending

    # --- Actions ---------------------------------------------------------

    def toggle_cove(self):
        if self.all_running():
            self.run_action(["disable"], "stop", "Stopping Cove…")
        else:
            self.run_action(["enable"], "start", "Starting Cove…")

    def reload_caddy(self):
        self.run_action(["reload"], "reload", "Reloading Caddy…")

    def run_action(self, args, name, busy_text, timeout=300, on_success=None):
        if self.busy:
            return
        self.busy = busy_text
        self.last_action_error = None
        self.last_user_action = time.monotonic()
        self.render()

        def work():
            status, output, error = run_cove(args, timeout)
            GLib.idle_add(self._finish_action, name, status, output, error, on_success)

        threading.Thread(target=work, daemon=True).start()

    def _finish_action(self, name, status, output, error, on_success):
        self.busy = None
        self.last_user_action = time.monotonic()
        log(f"cove {name}: exit {status}")
        if status != 0:
            self.report_failure(f"Could not {name} Cove" if name in ("start", "stop", "reload") else name,
                                error or output or f"cove {name} exited with an error.")
        elif on_success is not None:
            on_success(output)
        self.refresh_status()
        self.render()
        return False

    def report_failure(self, title, detail):
        self.last_action_error = title
        self.notify(f"{title} — {first_line(detail)}")
        log(f"{title}\n{strip_ansi(detail)}")
        self.render()

    def notify(self, body):
        log(f"notify: {body}")
        if HAVE_NOTIFY:
            try:
                Notify.Notification.new("Cove", body, os.path.join(ICON_DIR, "cove-logo.svg")).show()
                return
            except GLib.Error:
                pass
        if shutil.which("notify-send"):
            subprocess.Popen(["notify-send", "-a", "Cove", "Cove", body])

    # --- Sites submenu ----------------------------------------------------

    def list_sites(self):
        sites = []
        try:
            entries = sorted(os.listdir(SITES_DIR), key=str.lower)
        except OSError:
            return sites
        for entry in entries:
            path = os.path.join(SITES_DIR, entry)
            if not entry.endswith(".localhost") or not os.path.isdir(path):
                continue
            public = os.path.join(path, "public")
            try:
                modified = os.stat(public).st_mtime
            except OSError:
                try:
                    modified = os.stat(path).st_mtime
                except OSError:
                    modified = 0
            sites.append({
                "name": entry,
                "modified": modified,
                "wp": os.path.exists(os.path.join(public, "wp-config.php")),
            })
        return sites

    def rebuild_sites_menu(self):
        sites = self.list_sites()
        signature = [(site["name"], site["wp"], site["modified"]) for site in sites]
        if signature == self.sites_dir_mtime and self.sites_menu.get_children():
            return
        self.sites_dir_mtime = signature

        for child in self.sites_menu.get_children():
            self.sites_menu.remove(child)

        if len(sites) >= 8:
            self.add_item("Recent", sensitive=False, menu=self.sites_menu)
            for site in sorted(sites, key=lambda site: site["modified"], reverse=True)[:5]:
                self.add_site_entry(site)
            self.add_separator(self.sites_menu)

        for site in sites:
            self.add_site_entry(site)

        if sites:
            self.add_separator(self.sites_menu)
            self.sites_item.set_label(f"Sites ({len(sites)})")
        else:
            self.sites_item.set_label("Sites")

        self.add_item("New Site…", self.prompt_for_new_site, menu=self.sites_menu)
        self.sites_menu.show_all()

    def add_site_entry(self, site):
        host = site["name"]
        self.add_item(host, lambda h=host: open_uri(cove_url(h)), menu=self.sites_menu)
        # The panel renders this menu and never reports modifier keys, and
        # COSMIC cannot open a submenu inside a submenu, so the macOS
        # Option-key alternate becomes a flat, indented row under the site.
        if site["wp"]:
            self.add_item("      ↳ Log in as admin", lambda h=host: self.login_to_site(h), menu=self.sites_menu)

    def login_to_site(self, host):
        site_name = host[:-len(".localhost")] if host.endswith(".localhost") else host

        def opened(output):
            login_url = None
            for candidate in URL_PATTERN.findall(strip_ansi(output)):
                if host in candidate and "wp-login" in candidate:
                    login_url = candidate
            if login_url:
                open_uri(login_url)
            else:
                self.report_failure(f"Could not log in to {host}", "cove login did not return a login URL.")

        self.run_action(["login", site_name], f"log in to {host}", f"Logging in to {host}…",
                        timeout=45, on_success=opened)

    def prompt_for_new_site(self):
        dialog = Gtk.Dialog(title="New Cove Site")
        dialog.add_buttons("Cancel", Gtk.ResponseType.CANCEL, "Create", Gtk.ResponseType.OK)
        dialog.set_default_response(Gtk.ResponseType.OK)
        box = dialog.get_content_area()
        box.set_spacing(8)
        box.set_border_width(12)
        box.add(Gtk.Label(label="Creates a WordPress site at <name>.localhost.\n"
                                "Lowercase letters, numbers, and hyphens only.", xalign=0))
        entry = Gtk.Entry(placeholder_text="my-new-site", activates_default=True)
        box.add(entry)
        dialog.show_all()
        response = dialog.run()
        name = entry.get_text().strip().lower()
        dialog.destroy()
        if response != Gtk.ResponseType.OK or not name:
            return
        if not SITE_NAME_PATTERN.match(name):
            self.report_failure("Invalid site name",
                                "Site names can only contain lowercase letters, numbers, and hyphens, "
                                "and cannot begin or end with a hyphen.")
            return

        def created(_output):
            self.notify(f"{name}.localhost is ready — opening it now.")
            self.sites_dir_mtime = None
            open_uri(cove_url(f"{name}.localhost"))

        self.run_action(["add", name], f"create {name}.localhost",
                        f"Creating {name}.localhost… (takes about a minute)", timeout=240, on_success=created)

    # --- Launch at login ----------------------------------------------------

    def on_launch_toggled(self, item):
        if item.get_active():
            try:
                os.makedirs(os.path.dirname(AUTOSTART_FILE), exist_ok=True)
                with open(AUTOSTART_FILE, "w", encoding="utf-8") as handle:
                    handle.write(autostart_entry())
            except OSError as error:
                self.report_failure("Launch at Login", str(error))
        else:
            try:
                os.remove(AUTOSTART_FILE)
            except FileNotFoundError:
                pass
            except OSError as error:
                self.report_failure("Launch at Login", str(error))

    # --- Update check -------------------------------------------------------

    def on_update_tick(self):
        self.check_for_updates()
        return True

    def check_for_updates(self):
        def work():
            try:
                request = urllib.request.Request(
                    "https://github.com/anchorhost/cove/releases/latest", method="HEAD")
                with urllib.request.urlopen(request, timeout=15) as response:
                    tag = response.geturl().rstrip("/").rsplit("/", 1)[-1]
            except Exception:  # noqa: BLE001 — offline is not an error worth surfacing
                return
            if tag.startswith("v") and len(tag) > 1:
                GLib.idle_add(self._set_latest, tag[1:])

        threading.Thread(target=work, daemon=True).start()

    def _set_latest(self, version):
        self.latest_version = version
        self.render()
        return False

    # `cove upgrade` may install packages and ask questions, so it belongs in
    # a real terminal. Try the desktop's own terminal first, then common ones.
    def run_upgrade_in_terminal(self):
        self.last_user_action = time.monotonic()
        script = "cove upgrade; echo; read -r -p 'Press Enter to close.' _"
        candidates = [
            ("cosmic-term", ["--", "bash", "-lc", script]),
            ("x-terminal-emulator", ["-e", "bash", "-lc", script]),
            ("gnome-terminal", ["--", "bash", "-lc", script]),
            ("konsole", ["-e", "bash", "-lc", script]),
            ("xfce4-terminal", ["-e", f"bash -lc \"{script}\""]),
            ("alacritty", ["-e", "bash", "-lc", script]),
            ("kitty", ["bash", "-lc", script]),
            ("xterm", ["-e", "bash", "-lc", script]),
        ]
        for binary, args in candidates:
            if shutil.which(binary):
                subprocess.Popen([binary, *args], env=cove_env())
                return
        self.report_failure("Update Cove", "No terminal found. Run `cove upgrade` in a terminal.")


def autostart_entry():
    return (
        "[Desktop Entry]\n"
        "Type=Application\n"
        "Name=Cove Menu Bar\n"
        "Comment=Cove service status in the system tray\n"
        f"Exec={sys.executable} {os.path.join(INSTALL_DIR, 'cove-tray.py')}\n"
        f"Icon={os.path.join(INSTALL_DIR, 'cove-logo.svg')}\n"
        "Terminal=false\n"
        "X-GNOME-Autostart-enabled=true\n"
        "NoDisplay=true\n"
    )


def main():
    if "--autostart-entry" in sys.argv:
        sys.stdout.write(autostart_entry())
        return
    log("Cove Menu Bar started")
    CoveTray()
    Gtk.main()
    log("Cove Menu Bar quit")


if __name__ == "__main__":
    main()
COVE_MENUBAR_TRAY_EOF
}

# --- Embedded Adminer Theme (generated from adminer-theme/ by compile.sh) ---

emit_adminer_theme_css() {
cat <<'COVE_ADMINER_CSS_EOF'
/**
 * Cove — Adminer skin.
 * Matches the Cove landing page + dashboard (https://cove.run).
 *
 * Light/dark via prefers-color-scheme. Design tokens mirror
 * the Cove WordPress theme so the two UIs feel native together.
 */

/* ============================================
   Design tokens — Cove (light)
   ============================================ */
html {
  --bg:            #fbfaf7;
  --bg-elev:       #ffffff;
  --bg-sunk:       #f4f2ec;
  --bg-card:       #ffffff;
  --border:        #c9c4b6;
  --border-soft:   #dcd7ca;
  --border-strong: #9a948a;
  --brand:         oklch(48% 0.14 190);
  --text:          #1a1c1b;
  --text-soft:     #3a3d3a;
  --muted:         #6b6f6a;
  --dim:           #9a9d97;

  --accent:        oklch(62% 0.11 190);
  --accent-soft:   oklch(62% 0.11 190 / 0.10);
  --accent-ink:    oklch(35% 0.08 190);
  --accent-bright: oklch(72% 0.13 190);

  --ok:            oklch(60% 0.12 155);
  --ok-soft:       oklch(60% 0.12 155 / 0.12);
  --warn:          oklch(70% 0.14 70);
  --warn-soft:     oklch(70% 0.14 70 / 0.14);
  --err:           oklch(62% 0.18 25);
  --err-soft:      oklch(62% 0.18 25 / 0.14);

  /* Inked: hairlines do the work, corners near-square, nothing floats. */
  --radius-sm: 3px;
  --radius:    4px;
  --radius-lg: 6px;

  --font-sans:  'Geist', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono:  'Geist Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  --font-serif: 'Fraunces', 'Times New Roman', serif;

  /* Sidebar width (resizable via adminer.js drag handle, persisted in localStorage). */
  --menu-width: 240px;

  --shadow-sm: none;
  --shadow: none;
  --shadow-lg: none;

  /* Syntax colors */
  --syn-keyword: oklch(52% 0.14 290);
  --syn-string:  oklch(52% 0.13 155);
  --syn-number:  oklch(62% 0.14 60);
  --syn-comment: var(--dim);
  --syn-func:    var(--accent-ink);
  --syn-var:     oklch(55% 0.12 25);
  --syn-op:      var(--accent);
  --syn-type:    oklch(58% 0.13 70);
}

/* Design tokens — Cove (dark)
   Applies when: system prefers dark AND user hasn't explicitly chosen light,
   OR user has explicitly toggled to dark. adminer.js persists the choice. */
@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) {
    --bg:            #0f1210;
    --bg-elev:       #161a17;
    --bg-sunk:       #0b0e0c;
    --bg-card:       #181c19;
    --border:        #3a3f3a;
    --border-soft:   #2a2f2a;
    --border-strong: #565c56;
    --brand:         oklch(72% 0.12 190);
    --text:          #edeee9;
    --text-soft:     #c6c9c1;
    --muted:         #8a8e85;
    --dim:           #5d615a;

    --accent:        oklch(72% 0.12 190);
    --accent-soft:   oklch(72% 0.12 190 / 0.15);
    --accent-ink:    oklch(82% 0.10 190);
    --accent-bright: oklch(82% 0.13 190);

    --ok:            oklch(70% 0.13 155);
    --ok-soft:       oklch(70% 0.13 155 / 0.16);
    --warn:          oklch(78% 0.14 70);
    --warn-soft:     oklch(78% 0.14 70 / 0.18);
    --err:           oklch(72% 0.16 25);
    --err-soft:      oklch(72% 0.16 25 / 0.18);

    --shadow-sm: none;
    --shadow: none;
    --shadow-lg: none;

    --syn-keyword: oklch(76% 0.11 290);
    --syn-string:  oklch(78% 0.13 155);
    --syn-number:  oklch(80% 0.13 60);
    --syn-func:    var(--accent-ink);
    --syn-var:     oklch(78% 0.10 25);
    --syn-op:      var(--accent);
    --syn-type:    oklch(80% 0.13 70);
  }
}
html[data-theme="dark"] {
  --bg:            #0f1210;
  --bg-elev:       #161a17;
  --bg-sunk:       #0b0e0c;
  --bg-card:       #181c19;
  --border:        #3a3f3a;
  --border-soft:   #2a2f2a;
  --border-strong: #565c56;
  --brand:         oklch(72% 0.12 190);
  --text:          #edeee9;
  --text-soft:     #c6c9c1;
  --muted:         #8a8e85;
  --dim:           #5d615a;

  --accent:        oklch(72% 0.12 190);
  --accent-soft:   oklch(72% 0.12 190 / 0.15);
  --accent-ink:    oklch(82% 0.10 190);
  --accent-bright: oklch(82% 0.13 190);

  --ok:            oklch(70% 0.13 155);
  --ok-soft:       oklch(70% 0.13 155 / 0.16);
  --warn:          oklch(78% 0.14 70);
  --warn-soft:     oklch(78% 0.14 70 / 0.18);
  --err:           oklch(72% 0.16 25);
  --err-soft:      oklch(72% 0.16 25 / 0.18);

  --shadow-sm: none;
  --shadow: none;
  --shadow-lg: none;

  --syn-keyword: oklch(76% 0.11 290);
  --syn-string:  oklch(78% 0.13 155);
  --syn-number:  oklch(80% 0.13 60);
  --syn-func:    var(--accent-ink);
  --syn-var:     oklch(78% 0.10 25);
  --syn-op:      var(--accent);
  --syn-type:    oklch(80% 0.13 70);
}

/* ============================================
   Base & typography
   ============================================ */
body {
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  background: var(--bg);
  margin: 0;
  min-width: fit-content;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-feature-settings: "ss01", "cv11";
}

a {
  color: var(--accent-ink);
  text-decoration: none;
  transition: color 120ms ease;
}
a:visited { color: var(--accent-ink); }
a:link:hover,
a:visited:hover {
  color: var(--accent);
  text-decoration: none;
}
a.text:hover { text-decoration: none; }
a.jush-help:hover { color: inherit; }

/* ============================================
   Headers
   ============================================ */
h1 {
  font-size: 0.95rem;
  font-weight: 600;
  margin: 0;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-soft);
  color: var(--text);
  background: var(--bg-sunk);
  letter-spacing: -0.01em;
}

h2 {
  font-family: var(--font-serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1.65rem;
  letter-spacing: -0.02em;
  margin: 0 0 1.25rem 0;
  padding: 0;
  color: var(--text);
  background: transparent;
}

h3 {
  font-weight: 600;
  font-size: 1rem;
  letter-spacing: -0.01em;
  margin: 1.5rem 0 0.5rem;
  color: var(--text);
}

/* ============================================
   Layout — Sidebar menu
   ============================================ */
#menu {
  position: fixed;
  top: 0;
  left: 0;
  width: var(--menu-width);
  height: 100vh;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--bg-elev);
  border-right: 1px solid var(--border-soft);
  margin: 0;
  padding: 0;
  z-index: 100;
}

/* App brand */
#menu h1 {
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.08rem;
  font-weight: 500;
  letter-spacing: -0.015em;
  padding: 1rem 1.125rem 0.85rem;
  margin: 0;
  color: var(--text);
  background: var(--bg-elev);
  border-bottom: 1px solid var(--border-soft);
  position: sticky;
  top: 0;
  z-index: 10;
  white-space: nowrap;
}

/* Brand anchor (wraps the app name so it links back to the server home).
   Opt out of the #menu a sizing/hover rules — inherit h1 typography. */
#menu h1 a,
#menu h1 a#h1 {
  display: inline;
  padding: 0;
  margin: 0;
  font-family: inherit;
  font-size: inherit;
  font-style: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
  color: inherit;
  background: transparent;
  border-radius: 0;
}
#menu h1 a:hover {
  background: transparent;
  color: var(--accent-ink);
}
/* The Cove mark beside the app name (one drawing, one colour, per scheme). */
#menu h1 a#h1::before {
  content: '';
  display: inline-block;
  width: 22px; height: 22px;
  margin-right: 9px;
  vertical-align: -5px;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64' fill='none' stroke='%2300746f' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><circle cx='32' cy='32' r='26'/><path d='M 17 27 Q 24.5 20 32 27 T 47 27'/><path d='M 17 40 Q 24.5 33 32 40 T 47 40'/></svg>") no-repeat center / contain;
}
html[data-theme="dark"] #menu h1 a#h1::before { background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64' fill='none' stroke='%231dbcb5' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><circle cx='32' cy='32' r='26'/><path d='M 17 27 Q 24.5 20 32 27 T 47 27'/><path d='M 17 40 Q 24.5 33 32 40 T 47 40'/></svg>"); }
@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) #menu h1 a#h1::before { background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64' fill='none' stroke='%231dbcb5' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'><circle cx='32' cy='32' r='26'/><path d='M 17 27 Q 24.5 20 32 27 T 47 27'/><path d='M 17 40 Q 24.5 33 32 40 T 47 40'/></svg>"); }
}

/* Version chip under brand */
#menu h1 .version {
  display: inline-block;
  font-family: var(--font-mono);
  font-style: normal;
  font-size: 0.68rem;
  font-weight: 500;
  color: var(--muted);
  background: var(--bg-sunk);
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  padding: 1px 6px;
  margin-left: 6px;
  vertical-align: middle;
  letter-spacing: 0.02em;
}

/* Section labels (DB:, etc) */
#menu p {
  padding: 0.75rem 1.125rem 0.35rem;
  margin: 0;
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.13em;
  color: var(--dim);
  border-bottom: none;
}

/* Language selector */
#lang {
  position: relative;
  padding: 0.5rem 1.125rem 0.75rem;
  margin: 0;
  border-bottom: 1px solid var(--border-soft);
  top: auto; left: auto; right: auto;
}
#lang select { width: 100%; font-size: 0.82rem; }

/* Database dropdown */
#dbs {
  overflow: hidden;
  padding: 0.5rem 1.125rem 0.9rem;
  border-bottom: 1px solid var(--border-soft);
}
#dbs select { width: 100%; }

/* Menu links — general */
#menu a {
  display: inline;
  padding: 0.125rem 0.3rem;
  color: var(--text-soft);
  border-radius: var(--radius-sm);
  transition: background 120ms ease, color 120ms ease;
  font-size: 0.88rem;
}
#menu a:hover {
  background: var(--bg-sunk);
  color: var(--accent-ink);
}

/* Active state */
#menu a.active,
#menu .active > a,
#tables a.active {
  background: var(--accent-soft) !important;
  color: var(--accent-ink) !important;
  font-weight: 500;
}

#menu a.view { font-style: italic; opacity: 0.85; }

/* Logins + tables lists */
#logins,
#tables {
  padding: 0.5rem 1.125rem;
  margin: 0;
  border-bottom: 1px solid var(--border-soft);
  white-space: nowrap;
  overflow: hidden;
}
#logins li,
#tables li { list-style: none; margin: 0; padding: 0; }
#logins a,
#tables a,
#tables span { background: transparent; }

#tables a {
  display: inline;
  margin-right: 0.2rem;
}
#tables a[href*="table="],
#tables a[href*="view="] {
  font-family: var(--font-mono);
  font-weight: 500;
  font-size: 0.82rem;
  color: var(--text);
  padding: 0.15rem 0.4rem;
  border-radius: var(--radius-sm);
}
#tables a[href*="table="]:hover,
#tables a[href*="view="]:hover {
  background: var(--bg-sunk);
  color: var(--accent-ink);
}
#tables a[href*="table="].active,
#tables a[href*="view="].active,
#tables a[href*="table="]:target,
#tables a[href*="view="]:target,
#tables .active a[href*="table="],
#tables .active a[href*="view="] {
  background: var(--accent-soft) !important;
  color: var(--accent-ink) !important;
}

/* "select" action pill */
#tables a[href*="select="] {
  font-family: var(--font-mono);
  font-size: 0.62rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--dim);
  padding: 0.05rem 0.4rem;
  background: transparent;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  margin-left: 0.25rem;
}
#tables a[href*="select="]:hover {
  background: var(--accent-soft);
  color: var(--accent-ink);
  border-color: transparent;
}

/* Structure span pills */
#tables span { font-size: 0.72rem; color: var(--dim); }
#tables span a {
  font-family: var(--font-mono);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
  padding: 0.1rem 0.5rem;
  background: var(--bg-sunk);
  border: 1px solid var(--border-soft);
  border-radius: 999px;
}
#tables span a:hover {
  background: var(--accent-soft);
  color: var(--accent-ink);
  border-color: transparent;
}

/* Top-level nav links (SQL COMMAND, IMPORT, EXPORT, …) */
#menu > a {
  display: block;
  padding: 0.55rem 1.125rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  border-left: 2px solid transparent;
  border-radius: 0;
}
#menu > a:hover {
  background: var(--bg-sunk);
  border-left-color: var(--accent);
  color: var(--text);
}
#menu > a.active {
  background: var(--accent-soft);
  color: var(--accent-ink);
  border-left-color: var(--accent);
}

/* ============================================
   Layout — Main content & breadcrumb
   ============================================ */
#content {
  margin: 0 0 0 var(--menu-width);
  padding: 3.25rem 1.75rem 2.5rem 1.75rem;
  min-height: 100vh;
  background: var(--bg);
}

#breadcrumb {
  white-space: nowrap;
  position: fixed;
  top: 0;
  left: var(--menu-width);
  right: 0;
  background: color-mix(in oklab, var(--bg) 82%, transparent);
  backdrop-filter: saturate(140%) blur(12px);
  -webkit-backdrop-filter: saturate(140%) blur(12px);
  height: auto;
  line-height: 1.5;
  padding: 0.7rem 1.75rem;
  margin: 0;
  border-bottom: 1px solid var(--border-soft);
  z-index: 99;
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--muted);
}
#breadcrumb a { color: var(--muted); }
#breadcrumb a:hover { color: var(--accent-ink); }

/* Logout — hidden: Cove uses passwordless autologin, so the button is a no-op. */
.logout { display: none !important; }

/* Theme toggle (injected by adminer.js, sits left of the logout button) */
.cove-theme-toggle {
  position: fixed;
  top: 0.4rem;
  right: 1rem;
  z-index: 101;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-elev);
  color: var(--text-soft);
  cursor: pointer;
  box-shadow: none;
  transition: border-color 120ms, background 120ms, color 120ms;
}
.cove-theme-toggle:hover {
  background: var(--bg-sunk);
  border-color: var(--border-strong);
  color: var(--text);
}
.cove-theme-toggle svg {
  width: 15px;
  height: 15px;
  position: absolute;
  transition: opacity 200ms ease, transform 300ms ease;
}
.cove-theme-toggle svg { opacity: 0; transform: rotate(-40deg) scale(0.7); }
/* Icon shows the PREFERENCE (System = half disc), not just the paint. */
html[data-theme-pref="system"] .cove-theme-toggle .icon-system,
html[data-theme-pref="light"]  .cove-theme-toggle .icon-sun,
html[data-theme-pref="dark"]   .cove-theme-toggle .icon-moon { opacity: 1; transform: rotate(0) scale(1); }

/* Right-click menu on the toggle: System / Light / Dark */
.cove-theme-menu {
  position: fixed; top: 2.9rem; right: 1rem; z-index: 102;
  display: flex; flex-direction: column; min-width: 150px; padding: 4px;
  background: var(--bg-elev); border: 1px solid var(--border); border-radius: var(--radius);
}
.cove-theme-menu[hidden] { display: none; }
.cove-theme-menu button {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 7px 10px; border: 0; background: transparent; border-radius: var(--radius-sm);
  font: inherit; font-size: 0.88rem; color: var(--text-soft); text-align: left; cursor: pointer;
}
.cove-theme-menu button:hover { background: var(--bg-sunk); color: var(--text); }
.cove-theme-menu button[aria-checked="true"] { color: var(--text); }
.cove-theme-menu button[aria-checked="true"]::after { content: "\2713"; color: var(--accent); font-size: 0.85em; }

/* Auto sign-in interstitial (index.php's loginForm override) */
.cove-autologin { max-width: 520px; }
.cove-autologin-msg { font-size: 0.95rem; color: var(--text-soft); margin: 0 0 1rem; }
.cove-autologin-msg code { font-family: var(--font-mono); font-size: 0.85em; color: var(--text); }
.cove-autologin:not(.is-failed) input[type="submit"] { opacity: 0.6; }

.cove-menu-resize {
  position: fixed;
  top: 0;
  bottom: 0;
  left: calc(var(--menu-width) - 3px);
  width: 6px;
  z-index: 102;
  cursor: col-resize;
  background: transparent;
  transition: background 150ms ease;
  touch-action: none;
}
.cove-menu-resize:hover,
.cove-menu-resize.dragging {
  background: var(--accent-soft);
}
body.cove-menu-resizing {
  cursor: col-resize;
  user-select: none;
  -webkit-user-select: none;
}
body.cove-menu-resizing * {
  cursor: col-resize !important;
}

/* ============================================
   Tables
   ============================================ */
table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: inherit;
  margin: 0.75rem 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  /* clip, not hidden: `hidden` makes the table a scroll container, which
     pins the sticky <thead> 2.6rem below the table's own top edge and
     leaves an empty band above every header row. */
  overflow: clip;
  background: var(--bg-elev);
  box-shadow: var(--shadow-sm);
}

td table {
  width: 100%;
  margin: 0;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

td,
th {
  padding: 0.55rem 0.85rem;
  text-align: left;
  vertical-align: top;
  border: none;
  border-bottom: 1px solid var(--border-soft);
  background: inherit;
  margin: 0;
}
tr:last-child td,
tr:last-child th { border-bottom: none; }

th {
  background: var(--bg-sunk);
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
}
/* Row-header cells (the name column in database and table lists) follow
   their row; only the real column headers in <thead> get the sunk band. */
tbody th { background: inherit; font-weight: 500; }
/* Adminer's own stylesheet paints the checkbox cell with the page colour; let it follow its row. */
#content td.hover,
#content tr:hover td.hover,
#content .checkable .checked td.hover { background: inherit; }
#content thead td.hover { background: var(--bg-sunk); }

thead {
  position: sticky;
  top: 2.6rem;
  z-index: 10;
}
thead th,
thead td {
  background: var(--bg-sunk);
  border-bottom: 1px solid var(--border);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  padding: 0.6rem 0.85rem;
  text-align: left;
  white-space: nowrap;
}
thead th a,
thead td a { color: var(--muted); }
thead th a:hover,
thead td a:hover { color: var(--accent-ink); }
thead tr:hover td,
thead tr:hover th,
.js thead .checked th,
.js thead .checked td { background: var(--bg-sunk); }

.odds tbody tr:nth-child(2n) {
  background: color-mix(in oklab, var(--bg-sunk), transparent 50%);
}
tbody tr:hover td,
tbody tr:hover th { background: var(--accent-soft); }
#content td.check,
#content th.check { background: inherit; width: 1%; white-space: nowrap; padding-right: 0.5rem; }
#content td.check a { font-family: var(--font-mono); font-size: 0.72rem; color: var(--muted); margin-right: 0.35rem; }
#content td.check a:hover { color: var(--accent-ink); }

.js .checkable .checked td,
.js .checkable .checked th,
.js .checked td,
.js .checked th {
  background: var(--accent-soft) !important;
}

/* Column types */
.number,
.datetime,
.function { text-align: right; }
td[align="right"] { text-align: right; }

td.number {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  color: var(--text-soft);
}
.char { color: var(--syn-string); }
.date { color: var(--syn-keyword); }
.enum { color: var(--syn-type); }
.binary {
  color: var(--err);
  font-family: var(--font-mono);
  font-size: 0.85em;
}
td.null { color: var(--dim); font-style: italic; }

.view { font-style: italic; }
.active { font-weight: 600; }

.nowrap td,
.nowrap th,
td.nowrap,
p.nowrap { white-space: pre; }
.wrap td { white-space: normal; }

table code { font-size: 0.88rem; line-height: 1.45; }

/* Database-name cells (first column of a database list) feel like Cove site rows */
tbody tr td:first-child a {
  font-family: var(--font-mono);
  font-weight: 500;
  color: var(--text);
}
tbody tr td:first-child a:hover { color: var(--accent-ink); }

/* ============================================
   Forms & fieldsets
   ============================================ */
form { margin: 0; }

fieldset {
  display: inline-block;
  vertical-align: top;
  padding: 0.6rem 0.9rem 0.75rem;
  margin: 0.5rem 0.4rem 0 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-elev);
  box-shadow: none;
  min-height: auto;
}
/* Select / Search / Sort start collapsed: show them as a toggle chip, not an empty box. */
fieldset:has(> legend > a.toggle):has(> .hidden) {
  padding: 0.15rem 0.6rem 0.35rem;
  background: var(--bg-sunk);
}
legend a.toggle { text-decoration: none; color: var(--muted); }
legend a.toggle:hover { color: var(--accent-ink); }
legend a.toggle::after { content: ' +'; color: var(--dim); }
fieldset:has(> legend > a.toggle):not(:has(> .hidden)) legend a.toggle::after { content: ' \2212'; }
legend {
  padding: 0 0.4rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
}
fieldset div { margin-top: 0.4rem; }
fieldset select { margin-right: 0.25rem; }

input,
select,
textarea {
  font-family: inherit;
  font-size: 0.875rem;
  padding: 0.42rem 0.65rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-elev);
  color: var(--text);
  transition: border-color 120ms ease, box-shadow 120ms ease, background 120ms ease;
  box-sizing: border-box;
  vertical-align: middle;
}
input[type="checkbox"],
input[type="radio"] {
  width: 15px; height: 15px;
  padding: 0; margin: 0 0.15rem 0 0;
  border: 0; background: transparent; box-shadow: none;
  accent-color: var(--accent);
  vertical-align: -2px;
}
input:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}
input:hover,
select:hover,
textarea:hover { border-color: var(--border-strong); }

select {
  padding: 0.38rem 0.55rem;
  cursor: pointer;
}
option { padding: 0 5px; }
optgroup { font-size: 0.8rem; }

textarea,
.sqlarea {
  font-family: var(--font-mono);
  font-size: 0.88rem;
  line-height: 1.55;
  min-height: 150px;
}
.sqlarea {
  width: 98%;
  padding: 0.85rem;
  background: var(--bg-sunk);
  border-radius: var(--radius);
}

input.default { box-shadow: 0 0 0 3px var(--accent-soft); }
input.required,
input.maxlength { box-shadow: 0 0 0 3px var(--err-soft); }

input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--accent);
  width: 0.95rem;
  height: 0.95rem;
  cursor: pointer;
  border: none;
  padding: 0;
  vertical-align: middle;
}
input[type="radio"] { vertical-align: text-bottom; }

input[type="image"] {
  border: none;
  padding: 0;
  vertical-align: middle;
  opacity: 0.7;
  transition: opacity 120ms;
}
input[type="image"]:hover { opacity: 1; }

label input[type="checkbox"],
td input[type="radio"],
td span select { margin-right: 0.25rem; }

input.wayoff { left: -1000px; position: absolute; }

/* ============================================
   Buttons
   ============================================ */
input[type="submit"],
input[type="button"],
input[type="reset"],
button {
  font-family: inherit;
  font-size: 0.85rem;
  font-weight: 500;
  padding: 0.45rem 0.95rem;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--bg);
  cursor: pointer;
  transition: background 120ms ease, border-color 120ms ease, transform 80ms ease, box-shadow 120ms ease;
  box-shadow: var(--shadow-sm);
  letter-spacing: -0.005em;
}
input[type="submit"]:hover,
input[type="button"]:hover,
button:hover {
  background: var(--accent-bright);
  border-color: var(--accent-bright);
}
input[type="submit"]:active,
input[type="button"]:active,
button:active { transform: translateY(1px); }

input[type="reset"],
input[type="submit"][value="Cancel"] {
  background: var(--bg-elev);
  color: var(--text-soft);
  border-color: var(--border);
}
input[type="reset"]:hover,
input[type="submit"][value="Cancel"]:hover {
  background: var(--bg-sunk);
  border-color: var(--border-strong);
  color: var(--text);
}

/* Destructive submit buttons */
div input[name="delete"],
div input[name="drop"],
div input[name="truncate"],
input[value="Kill"] {
  background: var(--err);
  border-color: var(--err);
  color: var(--bg);
}
div input[name="delete"]:hover,
div input[name="drop"]:hover,
div input[name="truncate"]:hover,
input[value="Kill"]:hover {
  background: color-mix(in oklab, var(--err), white 10%);
  border-color: color-mix(in oklab, var(--err), white 10%);
}

/* ============================================
   Messages
   ============================================ */
.message {
  color: color-mix(in oklab, var(--ok), var(--text) 30%);
  background: var(--ok-soft);
  padding: 0.7rem 0.95rem;
  margin: 0.85rem 0;
  border-radius: var(--radius-sm);
  border-left: 3px solid var(--ok);
}
.message table {
  color: var(--text);
  background: var(--bg-elev);
  box-shadow: none;
}

.error {
  color: color-mix(in oklab, var(--err), var(--text) 30%);
  background: var(--err-soft);
  padding: 0.7rem 0.95rem;
  margin: 0.85rem 0;
  border-radius: var(--radius-sm);
  border-left: 3px solid var(--err);
}
.error b { background: transparent; font-weight: 600; }

/* ============================================
   Code & syntax
   ============================================ */
code {
  font-family: var(--font-mono);
  font-size: 0.88em;
  padding: 0.15rem 0.4rem;
  background: var(--bg-sunk);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  color: var(--text-soft);
}
code a:hover { background-color: transparent !important; }

pre {
  font-family: var(--font-mono);
  font-size: 0.88rem;
  line-height: 1.55;
  margin: 0.75rem 0 0;
}
pre, textarea {
  font: 0.88rem/1.55 var(--font-mono);
}
pre.jush {
  background: var(--bg-sunk);
  padding: 0.9rem;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  overflow-x: auto;
}
pre code {
  display: block;
  font-size: 100%;
  padding: 0;
  background: transparent;
  border: none;
}
td pre { margin: 0; }

/* JUSH syntax highlighting */
.jush-sql,
.jush-sql_code { color: var(--syn-keyword); font-weight: 600; }
.jush-apo,
.jush-quo,
.jush-sql_apo,
.jush-sql_quo { color: var(--syn-string); }
.jush-num { color: var(--syn-number); }
.jush-com,
.jush-sql_com { color: var(--syn-comment); font-style: italic; }
.jush-sql_function { color: var(--syn-func); }
.jush-op { color: var(--syn-op); }
.jush-var,
.jush-sql_var { color: var(--syn-var); }
.jush-bac,
.jush-sql_bac { color: var(--syn-type); }
/* Adminer 6 wraps keywords in doc-link anchors colored by jush's own
   --keyword-color (navy) — unreadable on the dark theme. Inherit the
   token color from the wrapping span instead. */
.jush a { color: inherit; }

/* ============================================
   Paragraphs, link groups, pagination
   ============================================ */
p { margin: 0.7rem 0; }

.links {
  margin: 0.85rem 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.links a {
  display: inline-block;
  white-space: nowrap;
  padding: 0.42rem 0.85rem;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-soft);
  font-weight: 500;
  font-size: 0.84rem;
  transition: background 120ms ease, border-color 120ms ease, color 120ms ease;
}
.links a:hover {
  background: var(--bg-sunk);
  border-color: var(--border-strong);
  color: var(--text);
}
.links a.active {
  background: var(--accent-soft);
  border-color: transparent;
  color: var(--accent-ink);
}

.pages { margin: 0.85rem 0; }
.pages a,
.pages b {
  display: inline-block;
  padding: 0.3rem 0.65rem;
  margin: 0.1rem;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-elev);
  color: var(--text-soft);
  text-decoration: none;
  font-family: var(--font-mono);
  font-size: 0.78rem;
}
.pages a:hover {
  background: var(--bg-sunk);
  border-color: var(--border-strong);
  color: var(--text);
}
.pages b {
  background: var(--accent-soft);
  border-color: transparent;
  color: var(--accent-ink);
  font-weight: 600;
}

/* ============================================
   Schema viz
   ============================================ */
#schema {
  margin-left: 60px;
  position: relative;
  user-select: none;
  -webkit-user-select: none;
}
#schema .table {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 0 2px;
  cursor: move;
  position: absolute;
  background: var(--bg-elev);
  box-shadow: var(--shadow);
}
#schema .table b {
  display: block;
  padding: 0.4rem 0.65rem;
  background: var(--accent);
  color: var(--bg);
  border-radius: 5px 5px 0 0;
  font-weight: 600;
  font-family: var(--font-mono);
  font-size: 0.82rem;
}
#schema .table a {
  display: block;
  padding: 0.2rem 0.65rem;
  font-size: 0.85rem;
  font-family: var(--font-mono);
}
#schema .table a:hover { background: var(--bg-sunk); }
#schema .references { position: absolute; }
#schema .arrow {
  height: 1.25em;
  background: url(data:image/gif;base64,R0lGODlhCAAKAIAAAICAgP///yH5BAEAAAEALAAAAAAIAAoAAAIPBIJplrGLnpQRqtOy3rsAADs=) no-repeat right center;
}

/* ============================================
   Help tooltip
   ============================================ */
#help {
  position: absolute;
  border: 1px solid var(--border);
  background: var(--bg-elev);
  padding: 0.5rem 0.75rem;
  font-family: var(--font-mono);
  font-size: 0.76rem;
  color: var(--text-soft);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow);
  z-index: 1000;
  max-width: 360px;
}
/* Neutralize syntax highlighting inside the tooltip — it's documentation
   for a single keyword, not an editable SQL snippet. */
#help * {
  color: inherit;
  font-weight: 500;
  font-style: normal;
}
#help a,
#help a:visited {
  color: var(--accent-ink);
}
#help a:hover {
  color: var(--accent);
}

/* ============================================
   Footer
   ============================================ */
.footer {
  position: sticky;
  bottom: 0;
  margin: 1.25rem -20px 0.5rem 0;
  box-shadow: 0 -5px 10px 10px var(--bg);
}
.footer > div {
  background: var(--bg);
  padding: 0 0 0.5rem;
}
.footer fieldset { margin-top: 0; }
.sql-footer { margin-bottom: 2rem; }

/* ============================================
   Misc
   ============================================ */
.time, .version {
  color: var(--dim);
  font-family: var(--font-mono);
  font-size: 0.72rem;
}
#version { color: var(--err); }
#h1 {
  color: var(--muted);
  text-decoration: none;
  font-style: italic;
}
#logo { vertical-align: baseline; margin-bottom: -3px; }

.block { display: block; }
.hidden { display: none; }
.js .hidden,
.nojs .jsonly { display: none; }
.help { cursor: help; }

.type { width: 15ex; }
.size { width: 7ex; }
.options select,
.options input { width: 20ex; }
.loadmore { margin-left: 1ex; }
.explain table { white-space: pre; }

/* Column sort indicator */
.js .column {
  position: absolute;
  background: var(--bg-elev);
  padding: 0.2rem 0.6rem 0.25rem 0;
  margin-top: -0.3rem;
  border: 1px solid var(--border);
  border-left: none;
  border-radius: 0 6px 6px 0;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
}

:target { background: var(--accent-soft); }

/* Icons */
.icon {
  width: 18px;
  height: 18px;
  background: var(--accent) center no-repeat;
  border: 0;
  padding: 0;
  vertical-align: middle;
  border-radius: 4px;
}
.icon span { display: none; }
.icon:hover { background-color: var(--accent-bright); }
.icon-up    { background-image: url(data:image/gif;base64,R0lGODlhEgASAIEAMe7u7gAAgJmZmQAAACH5BAEAAAEALAAAAAASABIAAQIghI+py+0PTQhRTgrvfRP0nmEVOIoReZphxbauAMfyHBcAOw==); }
.icon-down  { background-image: url(data:image/gif;base64,R0lGODlhEgASAIEAMe7u7gAAgJmZmQAAACH5BAEAAAEALAAAAAASABIAAQIghI+py+0PTQjxzCopvltX/lyix0wm2ZwdxraVAMfyHBcAOw==); }
.icon-plus  { background-image: url(data:image/gif;base64,R0lGODlhEgASAIEAMe7u7gAAgJmZmQAAACH5BAEAAAEALAAAAAASABIAAQIhhI+py+0PTQjxzCopvm/6rykgCHGVGaFliLXuI8TyTMsFADs=); }
.icon-cross { background-image: url(data:image/gif;base64,R0lGODlhEgASAIEAMe7u7gAAgJmZmQAAACH5BAEAAAEALAAAAAASABIAAQIjhI+py+0PIwph1kZvfnnDLoFfd2GU4THnsUruC0fCTNc2XQAAOw==); }
.icon-move  { background-image: url(data:image/gif;base64,R0lGODlhEgASAJEAAO7u7gAAAJmZmQAAACH5BAEAAAEALAAAAAASABIAAAIfhI+py+3vgpyU0Rug3gnX5U3cqIWSZZLqigjuC8dvAQA7); }

#menuopen { display: none; }

/* ============================================
   Responsive — Mobile
   ============================================ */
@media all and (max-width: 800px) {
  .cove-menu-resize { display: none; }
  .pages { left: auto; }
  .js .logout {
    top: 1.25rem;
    background-color: var(--bg);
    box-shadow: 0 0 5px 5px var(--bg);
  }
  #menu {
    position: static;
    width: 100%;
    height: auto;
    min-width: 23em;
    border-right: none;
    border-bottom: 1px solid var(--border-soft);
    background: var(--bg-elev);
    margin-top: 9px;
    box-shadow: var(--shadow);
  }
  #content {
    margin-left: 10px !important;
    padding-top: 1rem;
  }
  #lang { position: static; }
  #breadcrumb { position: static; left: auto !important; }
  .js #foot { position: absolute; top: 2em; left: 0; }
  .js .foot { display: none; }
  .js #menuopen {
    display: block;
    position: absolute;
    top: 3px;
    left: 6px;
  }
  .nojs #menu { position: static; }
  table { display: block; overflow-x: auto; }
  thead { position: static; }
}

/* ============================================
   Print
   ============================================ */
@media print {
  #lang, #menu, .logout { display: none; }
  #content { margin-left: 1em; padding-top: 0; }
  #breadcrumb { position: static; left: 1em; }
  body { background: white; color: black; }
  table { box-shadow: none; border: 1px solid #ccc; }
  .nowrap td, .nowrap th, td.nowrap { white-space: normal; }
}

/* ============================================
   RTL
   ============================================ */
.rtl h2 { margin: 0 -18px 1rem 0; }
.rtl p, .rtl table, .rtl .error, .rtl .message { margin: 0.75rem 0 0 20px; }
.rtl .logout { left: 1rem; right: auto; }
.rtl #content {
  margin: 0 var(--menu-width) 0 0;
  padding: 3.25rem 0 2.5rem 1.75rem;
}
.rtl #breadcrumb { left: auto; right: var(--menu-width); margin: 0; }
.rtl .pages { left: auto; right: var(--menu-width); }
.rtl input.wayoff { left: auto; right: -1000px; }
.rtl #lang, .rtl #menu { left: auto; right: 0; }
.rtl pre, .rtl code { direction: ltr; }
@media all and (max-width: 800px) {
  .rtl.js #foot { left: auto; right: 0; }
  .rtl .pages { right: auto; }
  .rtl.js #menuopen { left: auto; right: 6px; }
  .rtl #content { margin-left: 0 !important; margin-right: 10px; }
  .rtl #breadcrumb { left: auto !important; right: 48px; }
}
@media print {
  .rtl #content { margin-left: auto; margin-right: 1em; }
  .rtl #breadcrumb { left: auto; right: 1em; }
}

/* ============================================
   Scrollbars
   ============================================ */
* {
  scrollbar-width: thin;
  scrollbar-color: var(--border-strong) var(--bg-sunk);
}
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: var(--bg-sunk); }
*::-webkit-scrollbar-thumb {
  background: var(--border-strong);
  border-radius: 4px;
}
*::-webkit-scrollbar-thumb:hover { background: var(--muted); }

/* ============================================
   Image constraints
   ============================================ */
img { vertical-align: middle; border: 0; }
td img { max-width: 200px; max-height: 200px; }
COVE_ADMINER_CSS_EOF
}

emit_adminer_theme_js() {
cat <<'COVE_ADMINER_JS_EOF'
/**
 * Cove — Adminer UI enhancements.
 * Pairs with adminer.css. Adds:
 *   - Explicit light/dark theme toggle (persisted in localStorage).
 *   - Drag-to-resize sidebar (persisted in localStorage).
 *
 * index.php emits a tiny inline <script> earlier in <head> that sets
 * data-theme synchronously (before CSS applies) to avoid a theme flash.
 */
(function () {
  var KEY_THEME = 'cove-adminer-theme';
  var KEY_WIDTH = 'cove-adminer-menu-width';
  var MIN_W = 180, MAX_W = 480;
  var html = document.documentElement;

  /* ---------- Theme ----------
     Preference: 'light' | 'dark' | 'system' (default). data-theme carries the
     effective mode the tokens read; data-theme-pref drives the toggle icon.
     Click flips light and dark; right-click picks from a small menu. */
  function readPref() {
    try {
      var s = localStorage.getItem(KEY_THEME);
      if (s === 'dark' || s === 'light') return s;
    } catch (e) {}
    return 'system';
  }
  function osTheme() {
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  }
  function effective(pref) { return pref === 'system' ? osTheme() : pref; }

  function applyPref(pref) {
    pref = (pref === 'dark' || pref === 'light') ? pref : 'system';
    html.setAttribute('data-theme', effective(pref));
    html.setAttribute('data-theme-pref', pref);
    try { localStorage.setItem(KEY_THEME, pref); } catch (e) {}
    var btn = document.querySelector('.cove-theme-toggle');
    if (btn) {
      var label = { system: 'System', light: 'Light', dark: 'Dark' }[pref];
      btn.setAttribute('aria-label', 'Theme: ' + label + ' (click to switch light and dark, right-click for options)');
      btn.title = btn.getAttribute('aria-label');
    }
    var menu = document.querySelector('.cove-theme-menu');
    if (menu) {
      var items = menu.querySelectorAll('button');
      for (var i = 0; i < items.length; i++) items[i].setAttribute('aria-checked', String(items[i].getAttribute('data-pref') === pref));
    }
  }

  if (!html.hasAttribute('data-theme')) applyPref(readPref());
  try {
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function () {
      if (readPref() === 'system') applyPref('system');
    });
  } catch (e) {}

  /* ---------- Menu width ---------- */
  function clampWidth(w) {
    w = Math.round(w);
    if (w < MIN_W) return MIN_W;
    if (w > MAX_W) return MAX_W;
    return w;
  }

  function applyWidth(w) {
    w = clampWidth(w);
    html.style.setProperty('--menu-width', w + 'px');
    return w;
  }

  // Restore saved width synchronously (before first paint).
  try {
    var savedWidth = parseInt(localStorage.getItem(KEY_WIDTH), 10);
    if (savedWidth >= MIN_W && savedWidth <= MAX_W) applyWidth(savedWidth);
  } catch (e) {}

  /* ---------- Toggle button ---------- */
  var SUN  = '<svg class="icon-sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.41 1.41m11.32 11.32l1.41 1.41M2 12h2m16 0h2M4.93 19.07l1.41-1.41m11.32-11.32l1.41-1.41"/></svg>';
  var MOON = '<svg class="icon-moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>';
  var SYSTEM = '<svg class="icon-system" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 3a9 9 0 0 1 0 18z" fill="currentColor" stroke="none"/></svg>';

  function makeToggle() {
    if (document.querySelector('.cove-theme-toggle')) return;

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'cove-theme-toggle';
    btn.setAttribute('aria-haspopup', 'menu');
    btn.innerHTML = SYSTEM + SUN + MOON;

    var menu = document.createElement('div');
    menu.className = 'cove-theme-menu';
    menu.setAttribute('role', 'menu');
    menu.hidden = true;
    var prefs = [['system', 'System'], ['light', 'Light'], ['dark', 'Dark']];
    for (var i = 0; i < prefs.length; i++) {
      var item = document.createElement('button');
      item.type = 'button';
      item.setAttribute('role', 'menuitemradio');
      item.setAttribute('data-pref', prefs[i][0]);
      item.textContent = prefs[i][1];
      menu.appendChild(item);
    }
    document.body.appendChild(menu);

    btn.addEventListener('click', function () {
      menu.hidden = true;
      applyPref(effective(readPref()) === 'dark' ? 'light' : 'dark');
    });
    btn.addEventListener('contextmenu', function (e) {
      e.preventDefault();
      menu.hidden = !menu.hidden;
    });
    menu.addEventListener('click', function (e) {
      var b = e.target.closest('[data-pref]');
      if (!b) return;
      applyPref(b.getAttribute('data-pref'));
      menu.hidden = true;
    });
    document.addEventListener('click', function (e) {
      if (!menu.hidden && !e.target.closest('.cove-theme-menu, .cove-theme-toggle')) menu.hidden = true;
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && !menu.hidden) menu.hidden = true;
    });
    applyPref(readPref());

    var logout = document.querySelector('.logout');
    if (logout && logout.parentNode) {
      logout.parentNode.insertBefore(btn, logout);
    } else {
      document.body.appendChild(btn);
    }
  }

  /* ---------- Resize handle ---------- */
  function makeResizer() {
    if (document.querySelector('.cove-menu-resize')) return;

    var handle = document.createElement('div');
    handle.className = 'cove-menu-resize';
    handle.setAttribute('aria-hidden', 'true');
    handle.title = 'Drag to resize · double-click to reset';
    document.body.appendChild(handle);

    var active = false;

    handle.addEventListener('pointerdown', function (e) {
      e.preventDefault();
      try { handle.setPointerCapture(e.pointerId); } catch (err) {}
      active = true;
      handle.classList.add('dragging');
      document.body.classList.add('cove-menu-resizing');
    });
    handle.addEventListener('pointermove', function (e) {
      if (!active) return;
      applyWidth(e.clientX);
    });
    function end(e) {
      if (!active) return;
      active = false;
      try { handle.releasePointerCapture(e.pointerId); } catch (err) {}
      handle.classList.remove('dragging');
      document.body.classList.remove('cove-menu-resizing');
      var w = parseInt(html.style.getPropertyValue('--menu-width'), 10);
      if (w) {
        try { localStorage.setItem(KEY_WIDTH, String(w)); } catch (err) {}
      }
    }
    handle.addEventListener('pointerup', end);
    handle.addEventListener('pointercancel', end);
    handle.addEventListener('dblclick', function () {
      html.style.removeProperty('--menu-width');
      try { localStorage.removeItem(KEY_WIDTH); } catch (e) {}
    });
  }

  /* ---------- Brand link ----------
     On the login page Adminer wraps the name in <a id="h1"> pointing at
     adminer.org. On authenticated pages the name is a bare text node.
     Handle both: retarget if the anchor exists, otherwise wrap the text. */
  function retargetBrand() {
    var existing = document.getElementById('h1');
    if (existing && existing.tagName === 'A') {
      existing.setAttribute('href', '?server=&username=');
      existing.removeAttribute('target');
      existing.removeAttribute('rel');
      return;
    }

    var h1 = document.querySelector('#menu h1');
    if (!h1) return;
    for (var node = h1.firstChild; node; node = node.nextSibling) {
      if (node.nodeType === 3 && node.nodeValue.trim()) {
        var a = document.createElement('a');
        a.id = 'h1';
        a.href = '?server=&username=';
        a.textContent = node.nodeValue.trim();
        h1.replaceChild(a, node);
        return;
      }
    }
  }

  function init() {
    makeToggle();
    makeResizer();
    retargetBrand();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
COVE_ADMINER_JS_EOF
}

